/* ---------- formulários ---------- */
let M={};
const optA=(arr,sel)=>opt(arr.filter(x=>x.ativa!==false||x.id===sel),sel);
const opt=(arr,sel,fv=x=>x.id,ft=x=>x.nome)=>arr.map(x=>'<option value="'+esc(fv(x))+'"'+(String(fv(x))===String(sel)?' selected':'')+'>'+esc(ft(x))+'</option>').join('');
const addDias=(iso,n)=>{const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const nid=(p,arr)=>p+(arr.length+1);

function projNovo(){modal('Novo projeto','<label class="f" for="pn">Nome do projeto</label><input id="pn" placeholder="Ex.: Biblioteca comunitária"><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="proj-criar">Criar e abrir o cadastro</button>')}
function recEdit(){
 modal('Dados do recebimento','<label class="f" for="r1">Responsável pela elaboração e condução da proposta</label><input id="r1" value="'+esc(D.respElab)+'"><label class="f" for="r2">Cliente / parceiro</label><input id="r2" value="'+esc(D.pat)+'"><label class="f" for="r3">Instrumento</label><input id="r3" value="'+esc(D.instr)+'" placeholder="Ex.: Termo de Fomento nº 112/2026"><label class="f" for="r4">Códigos gerados pelo parceiro (um por linha, “rótulo: valor”)</label><textarea id="r4" rows="3">'+esc(D.codigos.map(c=>c.rot+': '+c.v).join('\n'))+'</textarea><label class="f" for="r5">Caracterização</label><select id="r5"><option value="">Selecione…</option>'+TIPOS.map(t=>'<option'+(t===D.tipo?' selected':'')+'>'+esc(t)+'</option>').join('')+'</select><div class="row" style="margin-top:6px"><input id="r5n" placeholder="Criar novo tipo (ex.: Convênio internacional)" style="flex:1"></div><div class="row"><div style="flex:1;min-width:140px"><label class="f" for="r6">Início do período do projeto</label><input type="date" id="r6" value="'+D.ini+'"></div><div style="flex:1;min-width:140px"><label class="f" for="r7">Fim do período do projeto</label><input type="date" id="r7" value="'+D.fim+'"></div></div>'+(D.etapa==='exec'?'<div class="small muted" style="margin-top:6px">A execução pode começar depois (ou terminar antes) do período do projeto. Os lançamentos só aceitam datas dentro da execução.</div><div class="row"><div style="flex:1;min-width:140px"><label class="f" for="r6e">Início da execução</label><input type="date" id="r6e" value="'+(D.exIni||'')+'"></div><div style="flex:1;min-width:140px"><label class="f" for="r7e">Fim da execução</label><input type="date" id="r7e" value="'+(D.exFim||'')+'"></div></div>':'')+'<label class="f" for="r8">Objetivo</label><textarea id="r8" rows="3">'+esc(D.objetivo)+'</textarea><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="rec-salvar">Salvar</button>');
}
function contaForm(id){const c=id?D.contas.find(x=>x.id===id):{};
 modal(id?'Editar conta bancária':'Nova conta bancária','<label class="f" for="cb">Banco</label><input id="cb" value="'+esc(c.banco||'')+'" placeholder="Ex.: Banco Esperança"><div class="row"><div style="flex:1;min-width:120px"><label class="f" for="cag">Agência</label><input id="cag" value="'+esc(c.ag||'')+'" placeholder="0123"></div><div style="flex:1;min-width:120px"><label class="f" for="cnu">Conta</label><input id="cnu" value="'+esc(c.num||'')+'" placeholder="45678-9"></div></div><label class="f" for="cob">Observações</label><textarea id="cob" rows="2">'+esc(c.obs||'')+'</textarea><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="conta-salvar" data-id="'+(id||'')+'">Salvar</button>')}
function ccForm(id){const c=id?D.cc.find(x=>x.id===id):{};
 modal(id?'Editar centro de custo':'Novo centro de custo','<div class="row"><div style="flex:1;min-width:110px"><label class="f" for="ccn">Número / código</label><input id="ccn" value="'+esc(c.cod||'')+'" placeholder="CC01"></div><div style="flex:3;min-width:180px"><label class="f" for="ccd">Descrição</label><input id="ccd" value="'+esc(c.desc||'')+'" placeholder="Operação"></div></div><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="cc-salvar" data-id="'+(id||'')+'">Salvar</button>')}
function bloqForm(id){const i=itemDe(id);modal('Bloquear item: '+i.nome,'<div class="alert warn">O item deixa de aceitar lançamentos. As previsões dos meses a partir de agora são zeradas (ficam só os valores já lançados). Meses travados não mudam.</div><label class="f" for="bj">Justificativa do bloqueio (aparece em "Observação para o usuário" do item)</label><textarea id="bj" rows="3"></textarea><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn d" data-a="item-bloq-ok" data-id="'+id+'">Bloquear item</button>')}
const INDT=[['aulas','Realizar N aulas'],['eventos','Realizar N eventos'],['alunos','Atender N pessoas'],['freq','Frequência mínima (%)'],['marco','Entrega concluída (sim ou não; alvo 1)']];
function metaCampos(p){return'<label class="f" for="mn'+p+'">Meta</label><input id="mn'+p+'" placeholder="Ex.: Realizar 30 aulas"><div class="row"><div style="flex:2;min-width:160px"><label class="f" for="mi'+p+'">Como medir</label><select id="mi'+p+'">'+INDT.map(x=>'<option value="'+x[0]+'">'+x[1]+'</option>').join('')+'</select></div><div style="flex:1;min-width:90px"><label class="f" for="ma'+p+'">Alvo</label><input id="ma'+p+'" type="number" min="1"></div></div>'}
function lerMeta(p){let a=parseFloat($('#ma'+p).value)||0;const i=$('#mi'+p).value;if(i==='freq')a=a/100;return{nome:$('#mn'+p).value.trim(),ind:i,alvo:a}}
function acaoForm(){modal('Nova ação do plano','<label class="f" for="an">Nome da ação</label><input id="an"><label class="f" for="at">Tipo</label><select id="at"><option value="aulas">Aulas (várias datas no calendário)</option><option value="evento">Evento / atividade pontual</option><option value="generico">Genérica (texto formatado, imagens e anexos)</option></select><div class="small muted" id="atd" style="margin-top:4px">Use a genérica para entregas que não são aulas nem eventos: relatórios, estudos, produtos. A comprovação é um texto formatado com imagens e anexos (planilhas, imagens e PDF).</div><h3 style="margin-top:14px">Primeira meta (obrigatória)</h3>'+metaCampos('')+'<div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="acao-salvar">Salvar ação</button>')}
function metaForm(id){modal('Nova meta — '+acaoDe(id).nome,metaCampos('')+'<div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="meta-salvar" data-id="'+id+'">Salvar meta</button>')}
function verbaForm(k,id){
 const r=k==='r',v=id?(r?D.receitas:D.verbas).find(x=>x.id===id):null;
 modal((v?'Editar ':'Nova ')+(r?'verba de receita':'verba'),'<label class="f" for="vn">Nome do tipo de '+(r?'receita':'verba')+'</label><input id="vn" value="'+esc(v?v.nome:'')+'" placeholder="'+(r?'Ex.: Repasse do parceiro':'Ex.: Verba Transporte')+'"><label class="f" for="vd">Explicação e observações para quem usa o orçamento</label><textarea id="vd" rows="3" placeholder="Aparece como nota ao passar o mouse sobre a verba no orçamento.">'+esc(v?v.desc||'':'')+'</textarea>'+'<div class="row"><div style="flex:1;min-width:160px"><label class="f" for="vc">Conta bancária</label><select id="vc">'+optA(D.contas,v?v.conta:'')+'</select></div><div style="flex:1;min-width:160px"><label class="f" for="vk">Centro de custo</label><select id="vk">'+optA(D.cc,v?v.cc:'')+'</select></div></div><div class="small muted">Os itens herdam esta conta e este centro de custo, e os lançamentos usam sempre os do cadastro. Só a coordenação altera.</div>'+(r?'':'<label class="chk"><input type="checkbox" id="vf"'+(v&&v.foto?' checked':'')+'> Exigir foto nos lançamentos desta verba</label>')+(D.etapa==='exec'?'<div class="alert warn" style="margin-top:8px">Projeto em execução: ao salvar será pedida a descrição da alteração (nova versão).</div>':'')+'<div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="verba-salvar" data-k="'+(k||'c')+'" data-id="'+(id||'')+'">Salvar</button>');
}
function itemForm(k,eid){
 const r=k==='r',grupos=r?D.receitas:D.verbas;
 if(!grupos.length){toast('Crie '+(r?'um tipo de receita':'uma verba')+' primeiro.');return}
 const it=eid?(r?rItens():itens()).find(x=>x.id===eid):null,ms=mesesProj();
 const rec=it&&it.rec==='unico'?'unico':'mensal',vm=it?(it.rec==='mensal'||it.rec==='unico'?it.valor:''):'',mm=it&&it.mes?it.mes:(ms[0]||''),ks=it&&it.mensal?Object.keys(it.mensal).sort():[],pi=(it&&it.ini)||ks[0]||ms[0]||'',pf=(it&&it.fim)||ks[ks.length-1]||ms[ms.length-1]||'';
 modal((it?'Editar item':(r?'Novo item de receita':'Novo item de verba')),'<label class="f" for="iv">'+(r?'Tipo de receita':'Verba')+'</label><select id="iv">'+opt(grupos,it?it.vid:'')+'</select><label class="f" for="in">Item</label><input id="in" value="'+esc(it?it.nome:'')+'" placeholder="'+(r?'Ex.: Parcela do repasse':'Ex.: Almoço')+'"><label class="f" for="im">Como ocorre</label><select id="im"><option value="mensal"'+(rec==='mensal'?' selected':'')+'>Mensal — o mesmo valor em todos os meses do período do projeto</option><option value="unico"'+(rec==='unico'?' selected':'')+'>Único — um valor em um só mês</option></select><div class="row"><div style="flex:1;min-width:130px"><label class="f" for="io" id="iol">Valor (R$)</label><input id="io" type="number" min="0" step="0.01" value="'+vm+'"></div><div style="flex:1;min-width:130px" id="imw"><label class="f" for="imm">Mês</label><select id="imm">'+ms.map(m=>'<option value="'+m+'"'+(m===mm?' selected':'')+'>'+mesNome(m)+'</option>').join('')+'</select></div></div><div class="row" id="ipw"><div style="flex:1;min-width:130px"><label class="f" for="ipi">Começa em</label><select id="ipi">'+ms.map(m=>'<option value="'+m+'"'+(m===pi?' selected':'')+'>'+mesNome(m)+'</option>').join('')+'</select></div><div style="flex:1;min-width:130px"><label class="f" for="ipf">Vai até</label><select id="ipf">'+ms.map(m=>'<option value="'+m+'"'+(m===pf?' selected':'')+'>'+mesNome(m)+'</option>').join('')+'</select></div></div><div id="itot" class="small muted"></div><div class="row"><div style="flex:1;min-width:160px"><label class="f" for="ic">Conta bancária</label><select id="ic">'+optA(D.contas,it?contaDe(it,grupos.find(g=>g.id===it.vid)):(grupos[0]&&grupos[0].conta))+'</select></div><div style="flex:1;min-width:160px"><label class="f" for="ik">Centro de custo</label><select id="ik">'+optA(D.cc,it?ccDe(it,grupos.find(g=>g.id===it.vid)):(grupos[0]&&grupos[0].cc))+'</select></div></div>'+(r?'<label class="chk"><input type="checkbox" id="irend"'+(it&&it.rend?' checked':'')+'> Rendimento financeiro (valor informado pelo setor financeiro)</label><div id="irmw" style="'+(it&&it.rend?'':'display:none')+'"><label class="f" for="irm">O que fazer com o rendimento?</label><select id="irm"><option value="">Escolha…</option><option value="soma"'+(it&&it.rendMod==='soma'?' selected':'')+'>Somar ao orçamento (entra no total de receitas)</option><option value="reserva"'+(it&&it.rendMod==='reserva'?' selected':'')+'>Reservar até o fim do contrato (fora do total de receitas, em linha própria)</option></select></div>':'')+''+(r?'':cotCampos(it)+'<label class="chk" style="margin-top:10px"><input type="checkbox" id="icm"'+(it&&it.cotMed?' checked':'')+'> <span><b>Exigir 3 orçamentos também na prestação de contas</b> (a cada lançamento da medição mensal): fornecedor, preço, anexo e marcação do escolhido, com nota fiscal e comprovante de pagamento do escolhido.</span></label>')+(r?'':docCampos(it))+'<label class="f" for="inota">Observação para o usuário</label><textarea id="inota" rows="2" placeholder="Aparece como nota ao passar o mouse sobre o item no orçamento.">'+esc(it?it.nota||'':'')+'</textarea>'+(it&&it.rec==='pers'?'<div class="alert warn" style="margin-top:8px">Este item tem distribuição personalizada. Ao salvar, ela será substituída pelo modelo escolhido acima.</div>':'')+(Object.keys(D.trava).length?'<div class="small muted" style="margin-top:6px">Meses travados ('+Object.keys(D.trava).map(mCurto).join(', ')+') mantêm o valor que já tinham.</div>':'')+(D.etapa==='exec'?'<div class="alert warn" style="margin-top:8px">Projeto em execução: ao salvar será pedida a descrição da alteração (nova versão).</div>':'')+'<div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="item-salvar" data-k="'+(k||'c')+'" data-id="'+(eid||'')+'">Salvar item</button>');
 itemForm.calc();
}
itemForm.calc=()=>{const u=$('#im').value==='unico';$('#imw').style.display=u?'':'none';$('#ipw').style.display=u?'none':'';$('#iol').textContent=u?'Valor único (R$)':'Valor por mês (R$)';const v=parseFloat($('#io').value)||0,a=$('#ipi').value,z=$('#ipf').value,n=u?1:mesesProj().filter(m=>m>=a&&m<=z).length;$('#itot').textContent=v?(u?'Total: '+brl(v):(n?'Total: '+brl(v*n)+' ('+n+' meses × '+brl(v)+')':'Período inválido: o início é depois do fim.')):''};
function rcbForm(iid,mes){
 const its=rItens();if(!its.length){toast('Nenhum item de receita cadastrado.');return}
 const dt=mes&&mes<HOJE.slice(0,7)?mes+'-05':HOJE;
 modal('Registrar recebimento','<label class="f" for="rci">Item de receita</label><select id="rci">'+its.map(i=>'<option value="'+i.id+'"'+(i.id===iid?' selected':'')+'>'+esc(i.vnome+' › '+i.nome)+'</option>').join('')+'</select><div class="row"><div style="flex:1;min-width:130px"><label class="f" for="rcd">Data do recebimento</label><input type="date" id="rcd" value="'+dt+'"></div><div style="flex:1;min-width:130px"><label class="f" for="rcv">Valor (R$)</label><input type="number" id="rcv" step="0.01" min="0"></div></div><label class="f" for="rcs">Descrição</label><input id="rcs" placeholder="Ex.: Repasse de dezembro"><label class="f" for="rcf">Comprovante (extrato, recibo)</label><input type="file" id="rcf" multiple><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="rcb-salvar">Registrar</button>');
}
function travaForm(m,un){
 modal((un?'Destravar ':'Travar ')+mesNome(m),un?'<div class="alert warn">Ao destravar, o mês volta a aceitar lançamentos, edições e exclusões. O motivo fica no histórico.</div><label class="f" for="tj">Motivo do destravamento</label><textarea id="tj" rows="2"></textarea><div id="le"></div>':'<p>Depois de travado, <b>ninguém</b> poderá lançar, editar, excluir, aprovar, devolver nem remanejar valores em '+mesNome(m)+'. Só o coordenador pode destravar, com justificativa.</p>'+(prestSt(m)!=='aprovada'?'<div class="alert warn">A prestação de contas deste mês ainda não foi aprovada pelo analista.</div>':''),'<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="trava-ok" data-m="'+m+'" data-u="'+(un?1:'')+'">'+(un?'Destravar':'Travar mês')+'</button>');
}
function exclForm(id){const l=D.lanc.find(x=>x.id===id);modal('Excluir '+l.id,'<div class="alert bad">Excluir remove o lançamento <b>'+esc(l.desc)+'</b> ('+$$(l.valor,l.v)+') do orçamento. Fica registrado no histórico.</div><label class="f" for="xm">Motivo da exclusão</label><textarea id="xm" rows="2"></textarea><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn d" data-a="lanc-excl-ok" data-id="'+id+'">Excluir lançamento</button>')}
function remForm(){
 const its=itens();
 modal('Remanejamento entre verbas','<p class="muted small" style="margin-top:0">Passa orçado de um item para outro de outra verba, em um mês. Precisa da aprovação do gestor do contrato. Entre itens da mesma verba não precisa: o saldo é livre.</p><label class="f" for="rm">Mês</label><select id="rm">'+mesesProj().map(m=>'<option value="'+m+'"'+(m===HOJE.slice(0,7)?' selected':'')+'>'+mesNome(m)+'</option>').join('')+'</select><label class="f" for="rd">Tirar de</label><select id="rd">'+its.map(i=>'<option value="'+i.id+'">'+esc(i.vnome+' › '+i.nome)+'</option>').join('')+'</select><label class="f" for="rp">Passar para</label><select id="rp">'+its.map((i,k)=>'<option value="'+i.id+'"'+(k===3?' selected':'')+'>'+esc(i.vnome+' › '+i.nome)+'</option>').join('')+'</select><label class="f" for="rv">Valor (R$)</label><input id="rv" type="number" step="0.01" min="0"><label class="f" for="rj">Justificativa</label><textarea id="rj" rows="2"></textarea><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="rem-enviar">Enviar ao gestor</button>');
}

/* ----- lançamento ----- */
const fileRow=()=>'<label class="f">Anexar documentos e fotos</label><div class="row"><select id="ft" style="width:auto"><option value="nf">Nota fiscal / recibo</option><option value="comp">Comprovante de pagamento</option><option value="foto">Foto</option></select><input type="file" id="fi" multiple style="flex:1;min-width:150px"></div><div id="fl" style="margin-top:6px"></div>';
const fileList=()=>{$('#fl').innerHTML=M.arq.map((x,i)=>'<span class="chip">'+(x.t==='foto'?'📷':'📎')+' '+esc(x.n)+' <small>('+DOCL[x.t]+')</small> <button class="crumb" data-a="rm-arq" data-id="'+i+'" aria-label="Remover">×</button></span>').join('')};
function tipoArq(n){return/\.(jpg|jpeg|png)$/i.test(n)?'foto':/pix|ted|compr/i.test(n)?'comp':'nf'}
function lancForm(l,vid,iid,mes){
 const v=l?l.v:vid,it=l?l.i:(iid||verbaDe(v).itens[0].id),dt=l?l.data:(mes&&mes<HOJE.slice(0,7)?mes+'-01':HOJE);
 M={id:l?l.id:null,arq:l?l.arq.map(n=>({n,t:(l.arqT&&l.arqT[n])||tipoArq(n)})):[]};
 const cot=(l&&l.cot)||{dispensa:false,just:'',itens:[]};
 const rows=[0,1,2].map(k=>{const c=cot.itens[k]||{f:'',v:''};return'<div class="cr" style="border:1px solid var(--line);border-radius:8px;padding:6px;margin-bottom:6px"><div class="row" style="margin-bottom:4px"><label class="chk" style="margin:0"><input type="radio" name="cesc" value="'+k+'"'+(cot.esc===k?' checked':'')+' aria-label="Orçamento escolhido '+(k+1)+'"> Escolhido</label><select id="cf'+k+'" style="flex:2;min-width:150px" aria-label="Fornecedor '+(k+1)+'"><option value="">Fornecedor '+(k+1)+'…</option>'+opt(D.prov,c.f)+'</select><input id="cv'+k+'" type="number" step="0.01" min="0" value="'+(c.v||'')+'" placeholder="Preço" style="flex:1;min-width:100px" aria-label="Preço do orçamento '+(k+1)+'"></div><div class="row"><span class="small muted">Anexo do orçamento:</span><input type="file" id="cq'+k+'" style="flex:1;min-width:140px">'+(c.arq?'<span class="chip" id="cqo'+k+'">📎 '+esc(c.arq)+'</span>':'')+'</div></div>'}).join('');
 modal(l?'Corrigir '+l.id:'Novo lançamento','<div class="row"><div style="flex:1;min-width:150px"><label class="f" for="lv1">Verba</label><select id="lv1">'+opt(D.verbas,v)+'</select></div><div style="flex:1;min-width:150px"><label class="f" for="li">Item</label><select id="li"></select></div></div><div id="lh"></div><div class="row"><div style="flex:1;min-width:150px"><label class="f" for="lt">Tipo</label><select id="lt">'+Object.keys(TIPOL).map(k=>'<option value="'+k+'"'+(l&&l.tipo===k?' selected':'')+'>'+TIPOL[k]+'</option>').join('')+'</select></div><div style="flex:1;min-width:150px"><label class="f" for="ld">Data</label><input type="date" id="ld" value="'+dt+'"></div></div><label class="f" for="ls">Descrição</label><input id="ls" value="'+esc(l?l.desc:'')+'" placeholder="O que foi comprado ou pago"><div class="row"><div style="flex:2;min-width:160px"><label class="f" for="lf">Prestador / fornecedor</label><select id="lf"><option value="">Selecione…</option>'+opt(D.prov,l?l.forn:'')+'</select></div><div style="flex:1;min-width:110px"><label class="f" for="lv">Valor (R$)</label><input id="lv" type="number" step="0.01" min="0" value="'+(l?l.valor:'')+'"></div></div><div class="small muted" style="margin-top:8px">Conta de saída e centro de custo vêm do cadastro do item (só a coordenação altera): <b id="lcx"></b></div>'+fileRow()+
  '<div id="cotbox" style="display:none;margin-top:10px"><h3>Orçamentos (mínimo 3)</h3><div class="small muted" style="margin-bottom:6px" id="cotmot"></div><div class="small muted" style="margin-bottom:6px">Informe fornecedor, preço e anexo de cada orçamento e marque o escolhido. Para o escolhido, anexe a nota fiscal e o comprovante de pagamento. Sem 3 orçamentos, é preciso justificar e o gestor do contrato aprova.</div><div id="cotrows">'+rows+'</div><label class="chk"><input type="checkbox" id="cdis"'+(cot.dispensa?' checked':'')+'> Não consegui 3 cotações: enviar justificativa ao gestor do contrato</label><textarea id="cjust" rows="2" placeholder="Justificativa" style="display:'+(cot.dispensa?'block':'none')+'">'+esc(cot.just||'')+'</textarea></div><div id="le"></div>',
  '<button class="btn" data-a="fechar">Cancelar</button><button class="btn" data-a="lanc-salvar" data-id="rascunho">Salvar rascunho</button><button class="btn p" data-a="lanc-salvar" data-id="lancar">Lançar</button>');
 fillItens(it);fileList();lancLive();
}
