function lancDet(l){
 const f=faltaDocs(l),cotp=reqCot(l)&&!cotOk(l),dv=D.div.filter(d=>d.l===l.id),vi=can(l.v);
 const cotH=reqCot(l)?'<h3 style="margin-top:12px">Cotações</h3>'+(l.cot&&l.cot.dispensa?'<div class="alert '+(l.cot.justSt==='aprovada'?'ok':l.cot.justSt==='recusada'?'bad':'warn')+'">Justificativa ('+(l.cot.justSt==='aprovada'?'aprovada':l.cot.justSt==='recusada'?'recusada':'aguardando o gestor')+'): '+esc(l.cot.just)+'</div>':(l.cot?l.cot.itens.map((c,k)=>'<div class="small">'+esc(provDe(c.f).nome)+': <b>'+$$(c.v,l.v)+'</b>'+(c.arq?' · 📎 '+esc(c.arq):'')+((l.cot.esc!=null?l.cot.esc===k:c.f===l.forn)?' ✓ escolhido':'')+'</div>').join(''):'<div class="alert bad">Sem cotações.</div>')):'';
 const podeAnalisar=has('lanc_analisa')&&l.st==='lancado';
 modal(l.id+' · '+l.desc,'<div class="row">'+pill(ST[l.st][0],ST[l.st][1])+'<b>'+$$(l.valor,l.v)+'</b></div><div class="small muted">'+fd(l.data)+' · '+esc(ctx(l))+' · '+esc(provDe(l.forn).nome)+' · '+TIPOL[l.tipo]+'</div><div class="small muted">'+esc((D.contas.find(c=>c.id===l.conta)||{nome:'—'}).nome)+' · '+esc((D.cc.find(c=>c.id===l.cc)||{nome:'—'}).nome)+'</div><h3 style="margin-top:12px">Comprovantes exigidos</h3>'+exigDocs(l).map(k=>'<div class="chk"><span>'+(l.docs[k]?'<span class="ok">✓</span>':'<span class="bad">✗</span>')+'</span>'+DOCL[k]+'</div>').join('')+'<div style="margin-top:6px">'+chips(l.arq)+'</div>'+cotH+
  (dv.length?'<h3 style="margin-top:12px">Divergências</h3>'+dv.map(d=>'<div class="alert '+(d.st==='encerrada'?'ok':'bad')+'">'+d.id+' ('+d.st+'): '+esc(d.texto)+(d.resp?'<div><i>Resposta: '+esc(d.resp)+'</i></div>':'')+'</div>').join(''):'')+
  '<h3 style="margin-top:12px">Histórico</h3>'+(l.hist.length?l.hist.map(h=>'<div class="small" style="border-left:3px solid var(--line);padding-left:8px;margin-bottom:6px"><b>'+fd(h.q)+'</b> · '+esc(h.quem)+' · '+esc(h.acao)+(h.txt?'<div><i>“'+esc(h.txt)+'”</i></div>':'')+'</div>').join(''):'<p class="muted small">Sem histórico.</p>')+
  (l.aval?'<div class="small" style="margin-top:8px">Avaliação do prestador neste lançamento: <b>'+l.aval+' / 5</b></div>':'')+
  (podeAnalisar?'<label class="f" for="mo">Motivo (obrigatório para devolver)</label><textarea id="mo" rows="2"></textarea><div id="le"></div>'+(f.length?'<div class="alert warn">Faltam comprovantes: '+f.map(k=>DOCL[k]).join(', ')+'. Não é possível aprovar.</div>':'')+(cotp?'<div class="alert warn">Cotações incompletas ou justificativa ainda não aprovada pelo gestor. Não é possível aprovar.</div>':''):''),
  '<button class="btn" data-a="fechar">Fechar</button>'+(has('aud_emite')?'<button class="btn" data-a="div-novo" data-id="'+l.id+'">Abrir divergência</button>':'')+((has('just_aprova')&&l.st==='aprovado'&&!l.aval)?'<button class="btn" data-a="aval" data-id="'+l.id+'">Avaliar prestador</button>':'')+(podeLancar()&&travado(mesDe(l))?'<span class="pill">🔒 mês travado: sem alterações</span>':'')+(podeLancar()&&!travado(mesDe(l))?'<button class="btn d" data-a="lanc-excl" data-id="'+l.id+'">Excluir</button>':'')+((podeLancar()&&!travado(mesDe(l))&&(l.st==='lancado'||l.st==='aprovado'))?'<button class="btn" data-a="lanc-edit" data-id="'+l.id+'">Editar'+(l.st==='aprovado'?' (volta para análise)':'')+'</button>':'')+((podeLancar()&&!travado(mesDe(l))&&(l.st==='rascunho'||l.st==='devolvido'))?'<button class="btn p" data-a="lanc-edit" data-id="'+l.id+'">Corrigir e relançar</button>':'')+(podeAnalisar?'<button class="btn d" data-a="lanc-dev" data-id="'+l.id+'">Devolver</button><button class="btn p" data-a="lanc-apr" data-id="'+l.id+'"'+((f.length||cotp)?' disabled':'')+'>Aprovar</button>':''));
}

