function fillRole(){$('#role').innerHTML=USUARIOS.filter(u=>u.ativo).map(u=>'<option value="'+u.id+'"'+(u.id===S.role?' selected':'')+'>'+esc(perfilDe(u.perfil).nome)+' — '+esc(u.nome)+'</option>').join('')}

function relForm(){
 const acs=D.acoes;modal('Relatório de execução das ações','<p class="muted small" style="margin-top:0">Escolha a ação e o período. O relatório é montado com o que foi registrado no sistema (aulas e eventos, presença, fotos, documentos e a prestação da ação).</p><label class="f" for="rac">Ação</label><select id="rac"><option value="*">Todas as ações</option>'+acs.map(a=>'<option value="'+a.id+'">'+esc(a.id+' · '+a.nome)+'</option>').join('')+'</select><div class="row"><div style="flex:1;min-width:140px"><label class="f" for="rde">De</label><input type="date" id="rde" value="'+(D.exIni||D.ini)+'"></div><div style="flex:1;min-width:140px"><label class="f" for="rat">Até</label><input type="date" id="rat" value="'+HOJE+'"></div></div><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="rel-gerar">Gerar relatório</button>');
}
function destForm(id){
 const d=id?DESTINOS.find(x=>x.id===id):null,tp=d?d.tipo:'storage';
 const campos=t=>DEST_TIPOS[t].campos.map(c=>'<label class="f" for="dc_'+c[0]+'">'+c[1]+(c[3]?'':' <span class="muted">(opcional)</span>')+'</label>'+(c[4]==='select'?'<select id="dc_'+c[0]+'">'+c[5].map(o=>'<option value="'+o[0]+'"'+((d&&d.p[c[0]]||'drive')===o[0]?' selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select>':'<input id="dc_'+c[0]+'" type="'+(c[4]||'text')+'" value="'+(c[4]==='password'?'':esc(d&&d.p[c[0]]||''))+'" placeholder="'+(c[4]==='password'&&d&&d.p[c[0]]?'(mantida — digite para trocar)':esc(c[2]))+'">')).join('');
 modal(d?'Configurar destino':'Novo destino de arquivos',(d?'<div class="small muted">Tipo: <b>'+esc(DEST_TIPOS[tp].nome)+'</b></div>':'<label class="f" for="dtp">Tipo</label><select id="dtp">'+Object.keys(DEST_TIPOS).map(k=>'<option value="'+k+'">'+esc(DEST_TIPOS[k].nome)+'</option>').join('')+'</select>')+'<label class="f" for="dnm">Nome deste destino</label><input id="dnm" value="'+esc(d?d.nome:'')+'"><div id="dcm">'+campos(tp)+'</div><label class="f" for="dpa">Modelo de pastas</label><input id="dpa" value="'+esc(d?d.pasta:'{processo}/{ano-mes}/{verba}')+'"><div class="small muted">Use {processo}, {ano}, {mes}, {ano-mes}, {verba}, {item} e {acao}. Exemplo hoje: <b id="dpv">'+esc(pastaPrev(d?d.pasta:''))+'</b>/</div><div id="le"></div>','<button class="btn" data-a="fechar">Cancelar</button><button class="btn p" data-a="dest-salvar" data-id="'+(id||'')+'">Salvar</button>');
 destForm.campos=campos;
}

const PDOC={files:[],tipo:'CPF'};
function dadosModal(id){
 const al=D.alunos.find(x=>x.id===id),h=new Date().toTimeString().slice(0,5),adm=has('aluno_gerir');PDOC.files=[];PDOC.tipo=TPDOC[0];
 modal('Dados protegidos — '+al.mat,'<div class="row">'+(al.foto?'<img src="'+al.foto+'" alt="Foto" style="width:72px;height:72px;border-radius:50%;object-fit:cover">':'<div style="width:72px;height:72px;border-radius:50%;background:var(--surface2)"></div>')+pill(catL(al),catA(al)==='atendido'?'info':'')+(adm?'<span style="flex:1"></span><label class="small muted" for="afo">'+(al.foto?'Trocar foto':'Adicionar foto')+'</label><input type="file" id="afo" accept="image/*" data-id="'+id+'" style="max-width:220px">':'')+'</div><div class="grid g2" style="gap:8px;margin-top:8px"><div><div class="muted small">Nome completo</div><b>'+esc(al.nome)+'</b></div><div><div class="muted small">Nome social</div>'+esc(al.social)+'</div><div><div class="muted small">Nascimento</div>'+fd(al.nasc)+' ('+idade(al)+' anos)</div><div><div class="muted small">Responsável</div>'+esc(al.resp)+'</div><div><div class="muted small">Endereço</div>'+esc(al.end)+'</div><div><div class="muted small">Telefone</div>'+esc(al.tel)+'</div></div><h3 style="margin:14px 0 4px">Documentos (área restrita)</h3>'+((al.docsP||[]).length?al.docsP.map((d,i)=>'<div class="row item"><b>'+esc(d.tipo)+'</b><span class="small muted" style="flex:1">'+esc(d.nome)+' · '+fd(d.q)+' · '+esc(d.quem)+'</span><button class="btn sm" data-a="pdoc-ver" data-id="'+id+'" data-i="'+i+'">Abrir</button>'+(adm?'<button class="btn sm d" data-a="pdoc-rm" data-id="'+id+'" data-i="'+i+'">Remover</button>':'')+'</div>').join(''):'<p class="muted small">Nenhum documento anexado.</p>')+(adm?'<div class="row" style="margin-top:6px"><select id="pdt" style="width:auto">'+TPDOC.map(x=>'<option>'+x+'</option>').join('')+'</select><input type="file" id="pdf" multiple style="flex:1;min-width:160px"><button class="btn sm" data-a="pdoc-add" data-id="'+id+'">Anexar</button></div>':'')+'<div class="alert info" style="margin-top:10px">Consulta registrada: '+esc(who())+', '+fd(HOJE)+' '+h+'. Cada abertura de documento também é registrada.</div>','<button class="btn p" data-a="fechar">Fechar</button>');
}

const docLinha=(d,custom)=>'<div class="row idr" style="gap:8px;align-items:center;margin-bottom:4px">'+(custom?'<input class="idn" value="'+esc(d.nome||'')+'" placeholder="Nome do documento (ex.: Contrato)" style="flex:2;min-width:160px" aria-label="Nome do documento">':'<label class="chk" style="flex:2;min-width:160px;margin:0"><input type="checkbox" class="idu" data-k="'+d.k+'"'+(d.usa?' checked':'')+'> '+esc(d.nome)+'</label>')+'<label class="chk" style="margin:0"><input type="checkbox" class="ido"'+(d.obrig?' checked':'')+(!custom&&!d.usa?' disabled':'')+' aria-label="Obrigatório"> Obrigatório</label>'+(custom?'<button type="button" class="btn sm d" data-a="idoc-rm">Remover</button>':'')+'</div>';
function docCampos(it){
 const cur=it?docsItem(it.id,it.vid):[{k:'nf',nome:DOCPAD[0].nome,obrig:true},{k:'comp',nome:DOCPAD[1].nome,obrig:true},{k:'foto',nome:DOCPAD[2].nome,obrig:false}];
 const pad=DOCPAD.map(p=>{const x=cur.find(d=>d.k===p.k);return docLinha({k:p.k,nome:p.nome,usa:!!x,obrig:!!(x&&x.obrig)},false)}).join(''),out=cur.filter(d=>!DOCPAD.some(p=>p.k===d.k)).map(d=>docLinha(d,true)).join('');
 return'<div style="margin-top:10px;padding:8px;border:1px solid var(--line);border-radius:8px"><b>Documentos a anexar nos lançamentos deste item</b><div class="small muted" style="margin:2px 0 6px">Marque os que fazem parte deste item e quais são obrigatórios. O lançamento só é enviado com os obrigatórios anexados; os demais são opcionais.</div>'+pad+'<div id="idl">'+out+'</div><button type="button" class="btn sm" data-a="idoc-add" style="margin-top:4px">+ Outro documento</button></div>';
}
function docsLer(){
 const l=[];document.querySelectorAll('.idu').forEach(u=>{if(u.checked){const p=DOCPAD.find(x=>x.k===u.dataset.k);l.push({k:p.k,nome:p.nome,obrig:u.closest('.idr').querySelector('.ido').checked})}});
 document.querySelectorAll('#idl .idr').forEach((r,n)=>{const nome=r.querySelector('.idn').value.trim();if(nome)l.push({k:'x'+n+'_'+nome.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'').slice(0,20),nome,obrig:r.querySelector('.ido').checked})});
 return l;
}
function ftSync(i,v){const s=$('#ft');if(!s)return;const ds=docsItem(i.id,v&&v.id),cur=s.value;s.innerHTML=ds.map(d=>'<option value="'+d.k+'">'+esc(d.nome)+(d.obrig?' (obrigatório)':' (opcional)')+'</option>').join('')||'<option value="nf">Documento</option>';if(cur&&s.querySelector('option[value="'+cur+'"]'))s.value=cur;fileList()}
